toolArgs.file_text:
.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    background-color: #2c2f33;
    color: #dcddde;
    padding: 1rem;
    overflow-y: auto;
    border-right: 1px solid #202225;
}

::deep .sidebar-title {
    color: #fff;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.75rem;
    padding: 0 0.5rem;
}

::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

::deep .channel-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    cursor: pointer;
    position: relative;
    transition: background-color 0.15s;
}

::deep .channel-item:hover {
    background-color: #36393f;
}

::deep .channel-item.active {
    background-color: #393c43;
    color: #fff;
}

::deep .channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    position: absolute;
    top: 0.5rem;
    right: 0.5rem;
    background-color: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 5px;
    border-radius: 8px;
    min-width: 16px;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    display: flex;
    flex-direction: column;
    background-color: #36393f;
    color: #dcddde;
    height: 100vh;
    overflow: hidden;
}

::deep .message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

::deep .message-area-header h4 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
}

::deep .channel-desc {
    margin: 0.25rem 0 0;
    font-size: 0.8rem;
    color: #8e9297;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

::deep .loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #8e9297;
    font-size: 0.85rem;
}

::deep .no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #8e9297;
}

/* Message Item */
::deep .message-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    position: relative;
    transition: background-color 0.1s;
}

::deep .message-item:hover {
    background-color: #32353b;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

::deep .message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9rem;
}

::deep .message-time {
    font-size: 0.7rem;
    color: #72767d;
}

::deep .message-content {
    margin-top: 0.2rem;
    font-size: 0.9rem;
    line-height: 1.4;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 0.4rem;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background-color: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 6px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dcddde;
    transition: background-color 0.1s;
}

::deep .reaction-badge:hover {
    background-color: #4f545c;
}

::deep .thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.25rem;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -0.75rem;
    right: 0.5rem;
    display: flex;
    gap: 2px;
    background-color: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px;
}

::deep .action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 0.75rem;
    padding: 4px 8px;
    cursor: pointer;
    border-radius: 3px;
}

::deep .action-btn:hover {
    background-color: #4f545c;
    color: #fff;
}

::deep .emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 2px;
    background-color: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 4px;
    z-index: 10;
}

::deep .emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 2px 4px;
    border-radius: 3px;
}

::deep .emoji-option:hover {
    background-color: #4f545c;
}

/* Message Input */
::deep .message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #202225;
    flex-shrink: 0;
    align-items: flex-end;
}

::deep .message-input textarea {
    flex: 1;
    resize: none;
    background-color: #40444b;
    border: none;
    border-radius: 8px;
    color: #dcddde;
    padding: 0.6rem 1rem;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
}

::deep .message-input textarea::placeholder {
    color: #72767d;
}

::deep .send-btn {
    background-color: #5865f2;
    color: #fff;
    border: none;
    border-radius: 4px;
    padding: 0.6rem 1.2rem;
    font-size: 0.85rem;
    font-weight: 500;
    cursor: pointer;
    transition: background-color 0.15s;
}

::deep .send-btn:hover:not(:disabled) {
    background-color: #4752c4;
}

::deep .send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    background-color: #2f3136;
    color: #dcddde;
    border-left: 1px solid #202225;
    display: flex;
    flex-direction: column;
    height: 100vh;
    overflow: hidden;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

::deep .thread-header h5 {
    margin: 0;
    color: #fff;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 3px;
}

::deep .close-btn:hover {
    background-color: #4f545c;
    color: #fff;
}

::deep .thread-root-message {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #202225;
    background-color: #36393f;
    flex-shrink: 0;
}

::deep .thread-root-message .message-author {
    font-size: 0.85rem;
}

::deep .thread-root-message .message-content {
    font-size: 0.85rem;
    color: #b9bbbe;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .thread-reply {
    padding: 0.4rem 0;
}

